#!/usr/bin/env node

/**
 * Deterministic synthetic workload generator for M01 saved-chat measurement.
 *
 * All expanded packages, SQLite databases, and CAS trees are generated into a
 * caller-owned empty directory. Nothing under live H2O storage is read or
 * written, and no generated bytes are a persistence authority.
 */

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { DatabaseSync } from 'node:sqlite';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(HERE, '../../../..');
const FIXED_ISO = '2026-08-23T00:00:00.000Z';
const FIXED_EPOCH = Date.parse(FIXED_ISO);
const GENERATOR_VERSION = 1;
const PACKAGE_SCHEMA = 'h2o.savedChatPackage';
const SNAPSHOT_SCHEMA = 'h2o.savedChatSnapshot';

const ASSET_SOURCES = [
  {
    relativePath: 'apps/studio/desktop/src-tauri/icons/32x32.png',
    expectedSha256: '2462cab3496a075c6262e2c687d8b5ad3b76b0a6be4301fc3bb6706af2c75661',
  },
  {
    relativePath: 'apps/studio/mobile/assets/images/favicon.png',
    expectedSha256: 'a4e030697a7571b3e95d31860e4da55d2f98e5e861e2b55e414f45a8556828ba',
  },
  {
    relativePath: 'apps/studio/mobile/assets/images/tabIcons/home.png',
    expectedSha256: '3829632ec7d495225395f5da3d0942935d7d055979b174613d1ade82fe420e76',
  },
  {
    relativePath: 'apps/studio/mobile/assets/images/tabIcons/explore.png',
    expectedSha256: 'e2dea1c2d20929d83e8eebd74818e808b1b72e376d3a1f3a03679fff0255d073',
  },
];

const DB_SCHEMA = `
CREATE TABLE chats (
  id TEXT PRIMARY KEY, source_id TEXT UNIQUE, title TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0,
  last_message_at INTEGER NOT NULL DEFAULT 0, message_count INTEGER NOT NULL DEFAULT 0,
  user_turn_count INTEGER NOT NULL DEFAULT 0, assistant_turn_count INTEGER NOT NULL DEFAULT 0,
  is_pinned INTEGER NOT NULL DEFAULT 0, is_archived INTEGER NOT NULL DEFAULT 0,
  is_starred INTEGER NOT NULL DEFAULT 0, is_deleted INTEGER NOT NULL DEFAULT 0,
  folder_id TEXT, category_id TEXT, project_id TEXT NOT NULL DEFAULT '',
  current_leaf_id TEXT, import_batch_id TEXT, meta_json TEXT NOT NULL DEFAULT '{}',
  is_saved INTEGER NOT NULL DEFAULT 0, is_linked INTEGER NOT NULL DEFAULT 0,
  linked_at INTEGER NOT NULL DEFAULT 0, linked_from TEXT NOT NULL DEFAULT '',
  link_source_href TEXT NOT NULL DEFAULT '', href TEXT, normalized_href TEXT,
  snapshot_count INTEGER NOT NULL DEFAULT 0, last_snapshot_id TEXT,
  last_captured_at INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX idx_chats_source_id ON chats(source_id);
CREATE INDEX idx_chats_updated_at ON chats(updated_at);
CREATE INDEX idx_chats_is_archived ON chats(is_archived);
CREATE INDEX idx_chats_folder_id ON chats(folder_id);
CREATE INDEX idx_chats_category_id ON chats(category_id);

CREATE TABLE snapshots (
  id TEXT PRIMARY KEY, chat_id TEXT NOT NULL, title TEXT NOT NULL DEFAULT '',
  digest TEXT, message_count INTEGER NOT NULL DEFAULT 0, pinned INTEGER NOT NULL DEFAULT 0,
  legacy INTEGER NOT NULL DEFAULT 0, captured_at INTEGER NOT NULL DEFAULT 0,
  updated_at INTEGER NOT NULL DEFAULT 0, meta_json TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX idx_snapshots_chat_id ON snapshots(chat_id);
CREATE INDEX idx_snapshots_captured_at ON snapshots(captured_at);
CREATE INDEX idx_snapshots_pinned ON snapshots(pinned);

CREATE TABLE snapshot_turns (
  snapshot_id TEXT NOT NULL, turn_idx INTEGER NOT NULL, role TEXT NOT NULL,
  outer_html TEXT NOT NULL DEFAULT '', text TEXT NOT NULL DEFAULT '',
  meta_json TEXT NOT NULL DEFAULT '{}', PRIMARY KEY (snapshot_id, turn_idx)
);
CREATE INDEX idx_snapshot_turns_role ON snapshot_turns(role);

CREATE TABLE assets (
  sha256 TEXT PRIMARY KEY, mime_type TEXT NOT NULL DEFAULT '', ext TEXT NOT NULL DEFAULT '',
  byte_size INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL DEFAULT '', refcount INTEGER NOT NULL DEFAULT 0,
  meta_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE snapshot_turn_assets (
  snapshot_id TEXT NOT NULL, turn_idx INTEGER NOT NULL, sha256 TEXT NOT NULL,
  relation TEXT NOT NULL DEFAULT 'inline', created_at TEXT NOT NULL DEFAULT '',
  meta_json TEXT NOT NULL DEFAULT '{}', PRIMARY KEY (snapshot_id, turn_idx, sha256)
);
CREATE INDEX idx_snapshot_turn_assets_sha256 ON snapshot_turn_assets(sha256);
`;

function fail(message) {
  throw new Error(message);
}

function parseArgs(argv) {
  if (argv.length !== 2 || argv[0] !== '--out' || !argv[1]) {
    fail('usage: node generate-workloads.mjs --out <empty-directory>');
  }
  return { out: path.resolve(argv[1]) };
}

function canonicalize(value) {
  if (Array.isArray(value)) return value.map(canonicalize);
  if (value && typeof value === 'object') {
    const out = {};
    for (const key of Object.keys(value).sort()) {
      if (typeof value[key] !== 'undefined') out[key] = canonicalize(value[key]);
    }
    return out;
  }
  return value;
}

function canonicalJson(value) {
  return JSON.stringify(canonicalize(value));
}

function sha256Hex(value) {
  return crypto.createHash('sha256').update(value).digest('hex');
}

function sha256(value) {
  return `sha256-${sha256Hex(value)}`;
}

function prepareRoot(root) {
  if (fs.existsSync(root)) {
    if (!fs.statSync(root).isDirectory()) fail('--out must be a directory path');
    if (fs.readdirSync(root).length) fail('--out directory must be empty');
  } else {
    fs.mkdirSync(root, { recursive: true });
  }
  return fs.realpathSync.native(root);
}

function writeFile(filePath, bytes) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, bytes, { flag: 'wx' });
}

function relative(root, target) {
  return path.relative(root, target).split(path.sep).join('/');
}

function makeBody(workload, index, targetBytes) {
  const prefix = `[${workload}:${String(index).padStart(5, '0')}] `;
  const unit = `synthetic-${workload}-${String(index).padStart(5, '0')}-abcdefghijklmnopqrstuvwxyz-0123456789 `;
  let text = prefix;
  while (Buffer.byteLength(text) < targetBytes) text += unit;
  return text.slice(0, targetBytes);
}

function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
}

function makeMessages(workload, count, bodyBytes, assets = [], assetMode = 'none') {
  const assetRefs = assets.map((asset) => asset.sha256);
  return Array.from({ length: count }, (_, index) => {
    const text = makeBody(workload, index, bodyBytes);
    const refs = assetMode === 'all'
      ? assetRefs.slice()
      : assetMode === 'first-20' && index < 20
        ? assetRefs.slice()
        : [];
    const message = {
      id: `msg-${workload.toLowerCase()}-${String(index).padStart(5, '0')}`,
      role: index % 2 === 0 ? 'user' : 'assistant',
      author: 'synthetic-fixture',
      createdAt: FIXED_ISO,
      turnIndex: index,
      parentId: index ? `msg-${workload.toLowerCase()}-${String(index - 1).padStart(5, '0')}` : '',
      contentText: text,
      content: [{ type: 'text', text }],
      assetRefs: refs,
      metadata: { fixtureWorkload: workload, logicalTurn: index },
    };
    if (refs.length) {
      const imageHtml = assets.map((asset) => `<img src="assets/${asset.sha256}.${asset.ext}" alt="">`).join('');
      const html = `<p>${escapeHtml(text)}</p>${imageHtml}`;
      message.contentHtml = html;
      message.content.push({ type: 'html', html, sanitized: true });
    }
    return message;
  });
}

function renderMarkdown(snapshot) {
  const lines = [
    `# ${snapshot.title}`,
    '',
    `- Studio chat id: \`${snapshot.chatId}\``,
    `- Snapshot id: \`${snapshot.snapshotId}\``,
    `- Captured: \`${snapshot.capturedAt}\``,
    '',
  ];
  for (const message of snapshot.messages) {
    const role = message.role.charAt(0).toUpperCase() + message.role.slice(1);
    lines.push(`## ${role} ${message.turnIndex || 0}`, '', message.contentText.trim(), '');
  }
  return lines.join('\n').replace(/\n{4,}/g, '\n\n\n');
}

function renderHtml(snapshot) {
  const parts = [
    '<!doctype html>',
    '<html lang="en">',
    '<head>',
    '<meta charset="utf-8">',
    '<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; img-src data: file: https:; style-src \'unsafe-inline\'; font-src data:; base-uri \'none\'; form-action \'none\'; frame-src \'none\'; object-src \'none\'">',
    '<meta name="viewport" content="width=device-width, initial-scale=1">',
    `<title>${escapeHtml(snapshot.title)}</title>`,
    '<style>',
    'body{font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;margin:2rem;line-height:1.5;color:#171717;background:#fff;}',
    'main{max-width:860px;margin:0 auto;}.meta{color:#666;font-size:.9rem;margin-bottom:1.5rem;}',
    '.msg{border-top:1px solid #ddd;padding:1rem 0;}.role{font-weight:700;margin-bottom:.5rem;}pre{white-space:pre-wrap;font:inherit;}',
    '</style>',
    '</head>',
    '<body>',
    '<main>',
    `<h1>${escapeHtml(snapshot.title)}</h1>`,
    `<div class="meta">Studio chat id: ${escapeHtml(snapshot.chatId)}<br>Snapshot id: ${escapeHtml(snapshot.snapshotId)}<br>Captured: ${escapeHtml(snapshot.capturedAt)}</div>`,
  ];
  for (const message of snapshot.messages) {
    const role = message.role.charAt(0).toUpperCase() + message.role.slice(1);
    const body = message.contentHtml || `<pre>${escapeHtml(message.contentText)}</pre>`;
    parts.push(`<section class="msg" data-turn-index="${message.turnIndex}">`);
    parts.push(`<div class="role">${escapeHtml(role)}</div>`);
    parts.push(`<div class="content">${body}</div>`);
    parts.push('</section>');
  }
  parts.push('</main>', '</body>', '</html>');
  return parts.join('\n');
}

function fileDescriptor(logicalPath, bytes, derivedFrom = null) {
  const descriptor = {
    path: logicalPath,
    byteLength: bytes.length,
    sha256: sha256(bytes),
  };
  if (derivedFrom) descriptor.derivedFrom = derivedFrom;
  return descriptor;
}

function createPackage(root, workload, options) {
  const chatId = options.chatId || `fixture-${workload.toLowerCase()}-chat`;
  const snapshotId = options.snapshotId || `snap_fixture_${workload.toLowerCase()}`;
  const assets = (options.assets || []).slice().sort((left, right) => left.sha256.localeCompare(right.sha256));
  const messages = options.messages;
  const schemaVersion = assets.length ? 2 : 1;
  const snapshot = {
    schema: SNAPSHOT_SCHEMA,
    schemaVersion,
    chatId,
    snapshotId,
    capturedAt: FIXED_ISO,
    savedAt: FIXED_ISO,
    title: `Synthetic ${workload}`,
    source: { host: '', nativeConversationId: '', sourceHref: '', accountHint: '' },
    library: {
      isLinked: false,
      isSaved: true,
      folderIdAtCapture: '',
      categoryIdAtCapture: '',
      projectIdAtCapture: '',
      labelIdsAtCapture: [],
      tagIdsAtCapture: [],
      linkSourceHref: '',
    },
    messages,
    metadata: {
      captureSurface: 'synthetic-fixture',
      captureAdapter: 'saved-chat-storage-workload-generator-v1',
      model: '',
      locale: 'en',
      timezone: 'UTC',
      digest: '',
      messageCount: messages.length,
    },
  };
  const snapshotBytes = Buffer.from(canonicalJson(snapshot));
  const markdownBytes = Buffer.from(renderMarkdown(snapshot));
  const htmlBytes = Buffer.from(renderHtml(snapshot));
  const snapshotHash = sha256(snapshotBytes);
  const contentHash = assets.length
    ? sha256(Buffer.from(canonicalJson({ snapshot: snapshotHash, assets: assets.map((asset) => asset.sha256) })))
    : snapshotHash;
  const files = {
    snapshot: fileDescriptor('snapshot.json', snapshotBytes),
    markdown: fileDescriptor('chat.md', markdownBytes, 'snapshot.json'),
    html: fileDescriptor('chat.html', htmlBytes, 'snapshot.json'),
  };
  const manifestAssets = assets.map((asset) => ({
    sha256: asset.sha256,
    path: `assets/${asset.sha256}.${asset.ext}`,
    mimeType: asset.mimeType,
    ext: asset.ext,
    byteLength: asset.bytes.length,
    source: 'synthetic-governed-image-fixture',
    sourceMessageId: messages.find((message) => message.assetRefs.includes(asset.sha256))?.id || '',
    turnRef: messages.findIndex((message) => message.assetRefs.includes(asset.sha256)),
  }));
  const manifest = {
    schema: PACKAGE_SCHEMA,
    schemaVersion,
    packageId: `pkg_${snapshotId}_${contentHash.slice(7, 19)}`,
    chatId,
    snapshotId,
    createdAt: FIXED_ISO,
    generatedAt: FIXED_ISO,
    generator: {
      surface: 'desktop',
      app: 'H2O Studio',
      appVersion: '',
      buildId: 'synthetic-fixture',
      rendererVersion: 'saved-chat-package-v1',
    },
    source: snapshot.source,
    store: {
      authority: 'desktop-sqlite-store',
      adapter: 'H2O.Studio.store',
      storeSchemaVersion: '',
      recordVersion: '',
      exportedFrom: 'desktop',
    },
    files,
    assets: manifestAssets,
    contentHash,
    provenance: {
      createdBy: 'saved-chat-storage-workload-generator',
      sourceOfTruth: 'desktop-sqlite-store',
      projectionOnly: true,
    },
  };
  if (assets.length) manifest.payloadVersion = 2;
  const packageDir = path.join(root, workload, `${chatId}.h2ochat`);
  writeFile(path.join(packageDir, 'snapshot.json'), snapshotBytes);
  writeFile(path.join(packageDir, 'chat.md'), markdownBytes);
  writeFile(path.join(packageDir, 'chat.html'), htmlBytes);
  for (const asset of assets) {
    writeFile(path.join(packageDir, 'assets', `${asset.sha256}.${asset.ext}`), asset.bytes);
  }
  writeFile(path.join(packageDir, 'manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`);
  return { packageDir, snapshot, contentHash };
}

function loadAssets() {
  return ASSET_SOURCES.map((source) => {
    const bytes = fs.readFileSync(path.join(REPO_ROOT, source.relativePath));
    const actual = sha256Hex(bytes);
    if (actual !== source.expectedSha256) fail(`governed asset fixture drift: ${source.relativePath}`);
    return {
      bytes,
      sha256: `sha256-${actual}`,
      ext: 'png',
      mimeType: 'image/png',
    };
  });
}

function logicalTurns(workload, count, bodyBytes, assetRefs = []) {
  return Array.from({ length: count }, (_, index) => {
    const text = makeBody(workload, index, bodyBytes);
    return {
      role: index % 2 === 0 ? 'user' : 'assistant',
      text,
      outerHtml: `<p>${escapeHtml(text)}</p>`,
      meta: { fixtureWorkload: workload, logicalTurn: index },
      assets: index < 20 ? assetRefs.slice() : [],
    };
  });
}

function snapshotDigest(turns) {
  return sha256(Buffer.from(canonicalJson(turns.map((turn) => ({
    role: turn.role,
    text: turn.text,
    outerHtml: turn.outerHtml,
    meta: turn.meta,
  })))));
}

function createDatabase(root, workload, state) {
  const dbPath = path.join(root, workload, 'studio-fixture.db');
  fs.mkdirSync(path.dirname(dbPath), { recursive: true });
  const db = new DatabaseSync(dbPath);
  try {
    db.exec(DB_SCHEMA);
    db.exec('BEGIN');
    const insertChat = db.prepare(`
      INSERT INTO chats (
        id, title, created_at, updated_at, last_message_at, message_count,
        user_turn_count, assistant_turn_count, is_saved, is_linked,
        current_leaf_id, meta_json, snapshot_count, last_snapshot_id, last_captured_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);
    const insertSnapshot = db.prepare(`
      INSERT INTO snapshots (
        id, chat_id, title, digest, message_count, captured_at, updated_at, meta_json
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `);
    const insertTurn = db.prepare(`
      INSERT INTO snapshot_turns (
        snapshot_id, turn_idx, role, outer_html, text, meta_json
      ) VALUES (?, ?, ?, ?, ?, ?)
    `);
    const insertAsset = db.prepare(`
      INSERT INTO assets (
        sha256, mime_type, ext, byte_size, created_at, updated_at, refcount, meta_json
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `);
    const insertJoin = db.prepare(`
      INSERT INTO snapshot_turn_assets (
        snapshot_id, turn_idx, sha256, relation, created_at, meta_json
      ) VALUES (?, ?, ?, ?, ?, ?)
    `);
    const refcounts = new Map();
    for (const chat of state.chats) {
      const snapshots = chat.snapshots;
      const finalSnapshot = snapshots.at(-1);
      const finalTurns = finalSnapshot?.turns || [];
      insertChat.run(
        chat.id,
        chat.title,
        FIXED_EPOCH,
        FIXED_EPOCH,
        finalSnapshot?.capturedAt || FIXED_EPOCH,
        finalTurns.length,
        finalTurns.filter((turn) => turn.role === 'user').length,
        finalTurns.filter((turn) => turn.role === 'assistant').length,
        1,
        0,
        finalSnapshot?.id || null,
        canonicalJson(chat.meta || {}),
        snapshots.length,
        finalSnapshot?.id || null,
        finalSnapshot?.capturedAt || 0,
      );
      for (const snapshot of snapshots) {
        insertSnapshot.run(
          snapshot.id,
          chat.id,
          snapshot.title,
          snapshotDigest(snapshot.turns),
          snapshot.turns.length,
          snapshot.capturedAt,
          FIXED_EPOCH,
          canonicalJson(snapshot.meta || {}),
        );
        snapshot.turns.forEach((turn, turnIndex) => {
          insertTurn.run(
            snapshot.id,
            turnIndex,
            turn.role,
            turn.outerHtml,
            turn.text,
            canonicalJson(turn.meta || {}),
          );
          for (const sha of [...new Set(turn.assets || [])].sort()) {
            insertJoin.run(snapshot.id, turnIndex, sha, 'inline', FIXED_ISO, '{}');
            refcounts.set(sha, (refcounts.get(sha) || 0) + 1);
          }
        });
      }
    }
    for (const asset of (state.assets || []).slice().sort((left, right) => left.sha256.localeCompare(right.sha256))) {
      insertAsset.run(
        asset.sha256,
        asset.mimeType,
        asset.ext,
        asset.bytes.length,
        FIXED_ISO,
        FIXED_ISO,
        refcounts.get(asset.sha256) || 0,
        '{}',
      );
    }
    db.exec('COMMIT');
  } catch (error) {
    try { db.exec('ROLLBACK'); } catch (_) { /* no active transaction */ }
    throw error;
  } finally {
    db.close();
  }
  return dbPath;
}

function createCas(root, workload, assets) {
  const casRoot = path.join(root, workload, 'cas');
  for (const asset of assets) {
    const hex = asset.sha256.slice('sha256-'.length);
    writeFile(path.join(casRoot, hex.slice(0, 2), asset.sha256), asset.bytes);
  }
  return casRoot;
}

function invocation(root, values) {
  const out = {};
  if (values.packages?.length) out.packages = values.packages.map((item) => relative(root, item));
  if (values.db) out.db = relative(root, values.db);
  if (values.cas) out.cas = relative(root, values.cas);
  if (values.sync) out.sync = relative(root, values.sync);
  return out;
}

function oneSnapshotChat(workload, turnCount, bodyBytes, meta = {}, assetRefs = []) {
  const turns = logicalTurns(workload, turnCount, bodyBytes, assetRefs);
  return {
    id: `fixture-${workload.toLowerCase()}-chat`,
    title: `Synthetic ${workload}`,
    meta,
    snapshots: [{
      id: `snap_fixture_${workload.toLowerCase()}`,
      title: `Synthetic ${workload}`,
      capturedAt: FIXED_EPOCH,
      meta,
      turns,
    }],
  };
}

function generate(root) {
  const assets = loadAssets();
  const workloads = [];

  const w01 = createPackage(root, 'W01', {
    messages: makeMessages('W01', 2, 64),
  });
  workloads.push({
    id: 'W01',
    source: 'generated real v1 .h2ochat',
    principalMetric: 'fixed package/schema overhead',
    inputs: invocation(root, { packages: [w01.packageDir] }),
    parameters: { messageCount: 2, bodyBytes: 64 },
  });

  const w02 = createPackage(root, 'W02', {
    messages: makeMessages('W02', 24, 512),
  });
  workloads.push({
    id: 'W02',
    source: 'generated real v1 .h2ochat',
    principalMetric: 'ordinary text/package scale',
    inputs: invocation(root, { packages: [w02.packageDir] }),
    parameters: { messageCount: 24, bodyBytes: 512 },
  });

  const w03 = createPackage(root, 'W03', {
    messages: makeMessages('W03', 72, 4096),
  });
  workloads.push({
    id: 'W03',
    source: 'generated real v1 .h2ochat',
    principalMetric: 'long-text compression and body-dominated package behavior',
    inputs: invocation(root, { packages: [w03.packageDir] }),
    parameters: { messageCount: 72, bodyBytes: 4096 },
  });

  const w04Turns = logicalTurns('W04', 8, 320);
  const w04Chat = {
    id: 'fixture-w04-history-chat',
    title: 'Synthetic W04',
    meta: { fixtureState: 'sequential-growth' },
    snapshots: Array.from({ length: 8 }, (_, index) => ({
      id: `snap_fixture_w04_${String(index + 1).padStart(2, '0')}`,
      title: 'Synthetic W04',
      capturedAt: FIXED_EPOCH + index * 1000,
      meta: { fixtureState: 'sequential-growth', sequence: index + 1 },
      turns: w04Turns.slice(0, index + 1),
    })),
  };
  const w04Db = createDatabase(root, 'W04', { chats: [w04Chat], assets: [] });
  workloads.push({
    id: 'W04',
    source: 'generated current-schema SQLite history',
    principalMetric: 'full-snapshot prefix growth and duplicated turn bodies',
    inputs: invocation(root, { db: w04Db }),
    parameters: { snapshotCount: 8, finalDistinctTurns: 8, appendPerSnapshot: 1, bodyBytes: 320 },
  });

  const image = assets[0];
  const w05Messages = makeMessages('W05', 8, 192, [image], 'all');
  const w05Package = createPackage(root, 'W05', { messages: w05Messages, assets: [image] });
  const w05Chat = oneSnapshotChat('W05', 8, 192, { fixtureState: 'image-heavy' }, [image.sha256]);
  const w05Db = createDatabase(root, 'W05', { chats: [w05Chat], assets: [image] });
  const w05Cas = createCas(root, 'W05', [image]);
  workloads.push({
    id: 'W05',
    source: 'generated real v2 package + SQLite registry + CAS',
    principalMetric: 'image references, package copy, CAS bytes, precompressed exclusion',
    inputs: invocation(root, { packages: [w05Package.packageDir], db: w05Db, cas: w05Cas }),
    parameters: { messageCount: 8, logicalAssetReferences: 8, distinctAssets: 1 },
  });

  const attachmentProxyAssets = assets.slice(0, 4);
  const w06Messages = makeMessages('W06', 6, 160, attachmentProxyAssets, 'all');
  const w06Package = createPackage(root, 'W06', { messages: w06Messages, assets: attachmentProxyAssets });
  const w06Chat = oneSnapshotChat('W06', 6, 160, { fixtureState: 'asset-heavy-attachment-proxy' }, attachmentProxyAssets.map((asset) => asset.sha256));
  const w06Db = createDatabase(root, 'W06', { chats: [w06Chat], assets: attachmentProxyAssets });
  const w06Cas = createCas(root, 'W06', attachmentProxyAssets);
  workloads.push({
    id: 'W06',
    source: 'generated supported image-asset-heavy proxy',
    principalMetric: 'multiple asset references and turn relationships',
    inputs: invocation(root, { packages: [w06Package.packageDir], db: w06Db, cas: w06Cas }),
    parameters: { messageCount: 6, logicalAssetReferences: 24, distinctAssets: 4 },
    governedLimitation: 'distinct non-image attachment class unsupported by current package schema',
  });

  const w07Packages = [];
  const w07Chats = [];
  for (let chatIndex = 1; chatIndex <= 2; chatIndex += 1) {
    const chatId = `fixture-w07-shared-${chatIndex}-chat`;
    const snapshotId = `snap_fixture_w07_shared_${chatIndex}`;
    const messages = makeMessages(`W07C${chatIndex}`, 3, 176, [image], 'all');
    w07Packages.push(createPackage(root, 'W07', {
      chatId,
      snapshotId,
      messages,
      assets: [image],
    }).packageDir);
    const turns = logicalTurns(`W07C${chatIndex}`, 3, 176, [image.sha256]);
    w07Chats.push({
      id: chatId,
      title: `Synthetic W07 chat ${chatIndex}`,
      meta: { fixtureState: 'shared-asset' },
      snapshots: [{
        id: snapshotId,
        title: `Synthetic W07 chat ${chatIndex}`,
        capturedAt: FIXED_EPOCH,
        meta: { fixtureState: 'shared-asset' },
        turns,
      }],
    });
  }
  const w07Db = createDatabase(root, 'W07', { chats: w07Chats, assets: [image] });
  const w07Cas = createCas(root, 'W07', [image]);
  workloads.push({
    id: 'W07',
    source: 'two real v2 packages + shared SQLite registry/CAS',
    principalMetric: 'cross-chat shared-asset reuse versus package copies',
    inputs: invocation(root, { packages: w07Packages, db: w07Db, cas: w07Cas }),
    parameters: { chatCount: 2, logicalAssetReferences: 6, packageAssetCopies: 2, distinctCasObjects: 1 },
  });

  const importedMeta = {
    recovered: {
      recoveredFromPackage: true,
      source: 'h2ochat-package-recovery',
      importer: 'archive-importer-h4',
      mode: 'import-as-new',
      originalChatId: 'fixture-w08-original-chat',
      originalSnapshotId: 'snap_fixture_w08_original',
      packagePath: 'archive/packages/fixture-w08-original-chat.h2ochat',
      packageDirName: 'fixture-w08-original-chat.h2ochat',
      originalCapturedAt: FIXED_ISO,
      recoveredAt: FIXED_ISO,
    },
  };
  const w08Chat = oneSnapshotChat('W08', 6, 256, importedMeta);
  w08Chat.id = 'fixture-w08-recovered-chat';
  w08Chat.snapshots[0].id = 'snap_fixture_w08_recovered';
  const w08Db = createDatabase(root, 'W08', { chats: [w08Chat], assets: [] });
  workloads.push({
    id: 'W08',
    source: 'generated current-schema import-as-new state',
    principalMetric: 'fresh recovered chat/snapshot storage shape',
    inputs: invocation(root, { db: w08Db }),
    parameters: { chatCount: 1, snapshotCount: 1, turnCount: 6 },
  });

  const restoredMeta = {
    restored: {
      restoredFromPackage: true,
      source: 'h2ochat-package-restore',
      restorer: 'archive-restore-k2',
      mode: 'restore-original-ids',
      originalChatId: 'fixture-w09-original-chat',
      originalSnapshotId: 'snap_fixture_w09_original',
      packagePath: 'archive/packages/fixture-w09-original-chat.h2ochat',
      packageDirName: 'fixture-w09-original-chat.h2ochat',
      originalCapturedAt: FIXED_ISO,
      restoredAt: FIXED_ISO,
    },
  };
  const w09Chat = oneSnapshotChat('W09', 6, 256, restoredMeta);
  w09Chat.id = 'fixture-w09-original-chat';
  w09Chat.snapshots[0].id = 'snap_fixture_w09_original';
  const w09Db = createDatabase(root, 'W09', { chats: [w09Chat], assets: [] });
  workloads.push({
    id: 'W09',
    source: 'generated current-schema restore-original-ids state',
    principalMetric: 'restored original identity storage shape',
    inputs: invocation(root, { db: w09Db }),
    parameters: { chatCount: 1, snapshotCount: 1, turnCount: 6 },
  });

  const w10Turns = logicalTurns('W10', 11, 288);
  const relinkMeta = {
    relink: {
      relinkedFromPackage: true,
      source: 'h2ochat-package-relink',
      relinker: 'archive-relink-k4',
      mode: 'relink',
      previousSnapshotId: 'snap_fixture_w10_previous',
      previousCurrentLeafId: 'snap_fixture_w10_previous',
      newSnapshotId: 'snap_fixture_w10_relinked',
      originalChatId: 'fixture-w10-package-chat',
      originalSnapshotId: 'snap_fixture_w10_package',
      packagePath: 'archive/packages/fixture-w10-package-chat.h2ochat',
      packageDirName: 'fixture-w10-package-chat.h2ochat',
      relinkedAt: FIXED_ISO,
      confirmToken: 'RELINK:fixture-w10-target-chat',
      confirmMode: 'typed-token',
    },
  };
  const w10Chat = {
    id: 'fixture-w10-target-chat',
    title: 'Synthetic W10',
    meta: { existing: true, relinked: relinkMeta.relink },
    snapshots: [
      {
        id: 'snap_fixture_w10_previous',
        title: 'Synthetic W10 previous',
        capturedAt: FIXED_EPOCH,
        meta: { fixtureState: 'preserved-previous-snapshot' },
        turns: w10Turns.slice(0, 10),
      },
      {
        id: 'snap_fixture_w10_relinked',
        title: 'Synthetic W10 relinked',
        capturedAt: FIXED_EPOCH + 1000,
        meta: relinkMeta,
        turns: w10Turns,
      },
    ],
  };
  const w10Db = createDatabase(root, 'W10', { chats: [w10Chat], assets: [] });
  workloads.push({
    id: 'W10',
    source: 'generated current-schema relink state',
    principalMetric: 'preserved previous snapshot plus full inserted relink snapshot',
    inputs: invocation(root, { db: w10Db }),
    parameters: { snapshotCount: 2, totalTurnsWritten: 21, distinctLogicalTurns: 11 },
  });

  const w11Messages = makeMessages('W11', 1200, 768, [image], 'first-20');
  const w11Package = createPackage(root, 'W11', { messages: w11Messages, assets: [image] });
  const w11Turns = logicalTurns('W11DB', 1000, 1024, [image.sha256]);
  const w11Chat = {
    id: 'fixture-w11-future-scale-chat',
    title: 'Synthetic W11',
    meta: { fixtureState: 'future-scale' },
    snapshots: Array.from({ length: 20 }, (_, index) => ({
      id: `snap_fixture_w11_${String(index + 1).padStart(2, '0')}`,
      title: 'Synthetic W11',
      capturedAt: FIXED_EPOCH + index * 1000,
      meta: { fixtureState: 'future-scale', sequence: index + 1 },
      turns: w11Turns.slice(0, (index + 1) * 50),
    })),
  };
  const w11Db = createDatabase(root, 'W11', { chats: [w11Chat], assets: [image] });
  const w11Cas = createCas(root, 'W11', [image]);
  workloads.push({
    id: 'W11',
    source: 'generated on-demand real v2 package + 20-snapshot SQLite history + CAS',
    principalMetric: 'future-scale analysis runtime and memory behavior',
    inputs: invocation(root, { packages: [w11Package.packageDir], db: w11Db, cas: w11Cas }),
    parameters: {
      packageMessageCount: 1200,
      packageBodyBytes: 768,
      snapshotCount: 20,
      finalDistinctTurns: 1000,
      totalTurnRows: 10500,
      sqliteBodyBytesPerTurn: 1024,
      repeatedAssetReferences: 20,
    },
  });

  const index = {
    generatorVersion: GENERATOR_VERSION,
    generatedAt: FIXED_ISO,
    packageSchema: PACKAGE_SCHEMA,
    snapshotSchema: SNAPSHOT_SCHEMA,
    workloads,
  };
  const indexText = `${JSON.stringify(canonicalize(index), null, 2)}\n`;
  writeFile(path.join(root, 'workloads.json'), indexText);
  return { index, indexHash: sha256(Buffer.from(canonicalJson(index))) };
}

try {
  const options = parseArgs(process.argv.slice(2));
  const root = prepareRoot(options.out);
  const result = generate(root);
  process.stdout.write(`${result.indexHash}\n`);
} catch (error) {
  process.stderr.write(`saved-chat workload generation failed: ${error.message}\n`);
  process.exitCode = 1;
}
